import test from 'node:test';import assert from 'node:assert/strict';import {validateLocalRaster,validateLocalRasterInspection,localRasterRequest} from './local-raster-client.js';
const id='00000000-0000-4000-8000-000000000001',asset={id,name:'own.tif',createdAt:'2026-10-14T00:00:00Z',bytes:300,sha256:'a'.repeat(64)};
const raster={jobId:id,sha256:asset.sha256,width:2,height:2,storageLayout:'strip',bands:[{index:1,dataType:'Float32',nodata:-9999}],crs:'EPSG:4326',bounds:[10,19.8,10.2,20],transform:[0.1,0,10,0,-0.1,20],pixelInterpretation:'area',previewDataUrl:'data:image/png;base64,YQ==',previewWidth:2,previewHeight:2,displayBand:1,displayRange:[0,100],limitations:[]};
test('local original is bounded and inspection must match its exact source hash',()=>{assert.equal(validateLocalRasterInspection(raster,asset),raster);assert.throws(()=>validateLocalRaster({...asset,bytes:32*1024*1024+1}));assert.throws(()=>validateLocalRaster({...asset,name:'../own.tif'}));assert.throws(()=>validateLocalRasterInspection({...raster,sha256:'b'.repeat(64)},asset));assert.throws(()=>validateLocalRasterInspection({...raster,archiveOriginal:{}},asset));});
test('native file-picker cancellation returns null without fabricating an import',async()=>{globalThis.window={__TAURI__:{core:{invoke:async command=>{assert.equal(command,'open_local_raster');return null;}}}};try{assert.equal(await localRasterRequest('open'),null);}finally{delete globalThis.window;}});
